def upgrade() -> None:
    conn = op.get_bind()

    op.add_column(
        "recipes",
        sa.Column("quarantined_at", sa.DateTime(timezone=True), nullable=True),
    )
    op.add_column("recipes", sa.Column("quarantine_reason", sa.Text(), nullable=True))
    op.execute(
        "CREATE INDEX ix_recipes_quarantined ON recipes (quarantined_at) "
        "WHERE quarantined_at IS NOT NULL"
    )

    ids = list(_SOURCE)

    # 1. Drop the corrupted component rows wholesale. Nothing FKs to
    #    recipe_components, so this is self-contained.
    conn.execute(
        text("DELETE FROM recipe_components WHERE recipe_id = ANY(CAST(:ids AS uuid[]))"),
        {"ids": ids},
    )

    # 2. Reinsert from source. Fires the aggregate trigger, which zeroes four
    #    nutrient columns — step 3 is what puts them back.
    rows = [
        {"rid": rid, "name": ing[0], "name_en": ing[1], "g": ing[2], "pos": pos}
        for rid, rec in _SOURCE.items()
        for pos, ing in enumerate(rec["ing"])
    ]
    conn.execute(
        text(
            """
            INSERT INTO recipe_components
                   (recipe_id, free_text_name, name_en, amount_g, position)
            VALUES (CAST(:rid AS uuid), :name, :name_en, :g, :pos)
            """
        ),
        rows,
    )

    # 3. Restore the authored nutrition. Targets `recipes`, so the trigger
    #    does not fire and cannot re-zero what step 2 just wiped.
    conn.execute(
        text(
            """
            UPDATE recipes SET
                kcal = :k, protein_g = :p, carbs_g = :c, fat_g = :f,
                fiber_g = :fi, sugar_g = :su, sodium_mg = :so, sat_fat_g = :sa,
                potassium_mg = :po, pregnancy_safe = :ps, folate_ug = :fo,
                iron_mg = :ir, calcium_mg = :ca, phosphorus_mg = :ph
             WHERE id = CAST(:rid AS uuid)
            """
        ),
        [
            {"rid": rid, **{k: v for k, v in rec.items() if k != "ing"}}
            for rid, rec in _SOURCE.items()
        ],
    )
    print(f"0031: restored {len(ids)} recipes, {len(rows)} component rows")  # noqa: T201

    # Guard against a silent no-op: the batch must actually be there. If a
    # future environment lacks these ids, fail loudly rather than "succeed"
    # having repaired nothing.
    live = conn.execute(
        text("SELECT count(*) FROM recipes WHERE id = ANY(CAST(:ids AS uuid[]))"),
        {"ids": ids},
    ).scalar_one()
    if live != len(ids):
        raise RuntimeError(
            f"0031: expected {len(ids)} meals_v4 recipes, found {live} — refusing to "
            "leave the catalog half-repaired"
        )

    # 4. The two whose authored kcal is still out of band.
    res = conn.execute(
        text(
            """
            UPDATE recipes SET
                quarantined_at = now(),
                quarantine_reason = 'meals_v4_kcal_below_slot_floor'
             WHERE id = ANY(CAST(:ids AS uuid[]))
            """
        ),
        {"ids": list(_OUT_OF_BAND)},
    )
    print(f"0031: quarantined {res.rowcount} out-of-band recipes")  # noqa: T201

    # 5. Guard — safe now that the duplicates are gone.
    op.execute(
        f"CREATE UNIQUE INDEX uq_recipe_components_exact "  # noqa: S608
        f"ON recipe_components ({_DUP_KEY}) NULLS NOT DISTINCT"
    )


def downgrade() -> None:
    # The pre-fix component rows are not restored: they were corruption, and
    # re-inserting them would violate the index this migration adds. The
    # 2026-07-17 pre-fix dump has them if they are ever genuinely needed.
    op.execute("DROP INDEX IF EXISTS uq_recipe_components_exact")
    op.execute("DROP INDEX IF EXISTS ix_recipes_quarantined")
    op.drop_column("recipes", "quarantine_reason")
    op.drop_column("recipes", "quarantined_at")
